import{_ as n,a0 as p,w as d,s as o,ao as h,I as l,x as i,a1 as a,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何使用 Vim 编辑多个文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Vim 编辑多个文件 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Vim 编辑多个文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Vim 编辑多个文件 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180317 How To Edit Multiple Files Using Vim Editor","title":"如何使用 Vim 编辑多个文件","tag":"201805","desc":""},"relativePath":"201805/20180317 How To Edit Multiple Files Using Vim Editor.md","filePath":"[post].md"}'),c={name:"201805/20180317 How To Edit Multiple Files Using Vim Editor.md"};function g(r,s,k,b,u,f){const e=p("Link");return d(),o("div",null,[s[13]||(s[13]=h(`<h1 id="如何使用-vim-编辑多个文件" tabindex="-1">如何使用 Vim 编辑多个文件 <a class="header-anchor" href="#如何使用-vim-编辑多个文件" aria-label="Permalink to “如何使用 Vim 编辑多个文件”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/03/Edit-Multiple-Files-Using-Vim-Editor-720x340.png" alt=""></p><p>有时候，您可能需要修改多个文件，或要将一个文件的内容复制到另一个文件中。在图形用户界面中，您可以在任何图形文本编辑器（如 gedit）中打开文件，并使用 <code>CTRL + C</code> 和 <code>CTRL + V</code> 复制和粘贴内容。在命令行模式下，您不能使用这种编辑器。不过别担心，只要有 <code>vim</code> 编辑器就有办法。在本教程中，我们将学习使用 <code>vim</code> 编辑器同时编辑多个文件。相信我，很有意思哒。</p><h3 id="安装-vim" tabindex="-1">安装 Vim <a class="header-anchor" href="#安装-vim" aria-label="Permalink to “安装 Vim”">​</a></h3><p>Vim 编辑器可在大多数 Linux 发行版的官方软件仓库中找到，所以您可以用默认的软件包管理器来安装它。例如，在 Arch Linux 及其变体上，您可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S vim</span></span></code></pre></div><p>在 Debian 和 Ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install vim</span></span></code></pre></div><p>在 RHEL 和 CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install vim</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install vim</span></span></code></pre></div><p>在 openSUSE 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo zypper install vim</span></span></code></pre></div><h3 id="使用-linux-的-vim-编辑器同时编辑多个文件" tabindex="-1">使用 Linux 的 Vim 编辑器同时编辑多个文件 <a class="header-anchor" href="#使用-linux-的-vim-编辑器同时编辑多个文件" aria-label="Permalink to “使用 Linux 的 Vim 编辑器同时编辑多个文件”">​</a></h3><p>现在让我们谈谈正事，我们可以用两种方法做到这一点。</p><h4 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h4><p>有两个文件，即 <code>file1.txt</code> 和 <code>file2.txt</code>，带有一堆随机单词：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat file1.txt</span></span>
<span class="line"><span>ostechnix</span></span>
<span class="line"><span>open source</span></span>
<span class="line"><span>technology</span></span>
<span class="line"><span>linux</span></span>
<span class="line"><span>unix</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat file2.txt</span></span>
<span class="line"><span>line1</span></span>
<span class="line"><span>line2</span></span>
<span class="line"><span>line3</span></span>
<span class="line"><span>line4</span></span>
<span class="line"><span>line5</span></span></code></pre></div><p>现在，让我们同时编辑这两个文件。请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim file1.txt file2.txt</span></span></code></pre></div><p>Vim 将按顺序显示文件的内容。首先显示第一个文件的内容，然后显示第二个文件，依此类推。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-1-1.png" alt=""></p><h5 id="在文件中切换" tabindex="-1">在文件中切换 <a class="header-anchor" href="#在文件中切换" aria-label="Permalink to “在文件中切换”">​</a></h5><p>要移至下一个文件，请键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:n</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-2.png" alt=""></p><p>要返回到前一个文件，请键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:N</span></span></code></pre></div><p>如果有任何未保存的更改，Vim 将不允许您移动到下一个文件。要保存当前文件中的更改，请键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ZZ</span></span></code></pre></div><p>请注意，是两个大写字母 <code>ZZ</code>（<code>SHIFT + zz</code>）。</p><p>要放弃更改并移至上一个文件，请键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:N!</span></span></code></pre></div><p>要查看当前正在编辑的文件，请键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffers</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-5.png" alt=""></p><p>您将在底部看到加载文件的列表。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-6.png" alt=""></p><p>要切换到下一个文件，请输入 <code>:buffer</code>，后跟缓冲区编号。例如，要切换到第一个文件，请键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffer 1</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-7.png" alt=""></p><h5 id="打开其他文件进行编辑" tabindex="-1">打开其他文件进行编辑 <a class="header-anchor" href="#打开其他文件进行编辑" aria-label="Permalink to “打开其他文件进行编辑”">​</a></h5><p>目前我们正在编辑两个文件，即 <code>file1.txt</code> 和 <code>file2.txt</code>。我想打开另一个名为 <code>file3.txt</code> 的文件进行编辑。</p><p>您会怎么做？这很容易。只需键入 <code>:e</code>，然后输入如下所示的文件名即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:e file3.txt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-8.png" alt=""></p><p>现在你可以编辑 <code>file3.txt</code> 了。</p><p>要查看当前正在编辑的文件数量，请键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffers</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-10-1.png" alt=""></p><p>请注意，对于使用 <code>:e</code> 打开的文件，您无法使用 <code>:n</code> 或 <code>:N</code> 进行切换。要切换到另一个文件，请输入 <code>:buffer</code>，然后输入文件缓冲区编号。</p><h5 id="将一个文件的内容复制到另一个文件中" tabindex="-1">将一个文件的内容复制到另一个文件中 <a class="header-anchor" href="#将一个文件的内容复制到另一个文件中" aria-label="Permalink to “将一个文件的内容复制到另一个文件中”">​</a></h5><p>您已经知道了如何同时打开和编辑多个文件。有时，您可能想要将一个文件的内容复制到另一个文件中。这也是可以做到的。切换到您选择的文件，例如，假设您想将 <code>file1.txt</code> 的内容复制到 <code>file2.txt</code> 中：</p><p>首先，请切换到 <code>file1.txt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffer 1</span></span></code></pre></div><p>将光标移动至在想要复制的行的前面，并键入<code>yy</code> 以抽出（复制）该行。然后，移至 <code>file2.txt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffer 2</span></span></code></pre></div><p>将光标移至要从 <code>file1.txt</code> 粘贴复制行的位置，然后键入 <code>p</code>。例如，您想要将复制的行粘贴到 <code>line2</code> 和 <code>line3</code> 之间，请将鼠标光标置于行前并键入 <code>p</code>。</p><p>输出示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>line1</span></span>
<span class="line"><span>line2</span></span>
<span class="line"><span>ostechnix</span></span>
<span class="line"><span>line3</span></span>
<span class="line"><span>line4</span></span>
<span class="line"><span>line5</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-11.png" alt=""></p><p>要保存当前文件中所做的更改，请键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ZZ</span></span></code></pre></div><p>再次提醒，是两个大写字母 ZZ（<code>SHIFT + z</code>）。</p><p>保存所有文件的更改并退出 vim 编辑器，键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:wq</span></span></code></pre></div><p>同样，您可以将任何文件的任何行复制到其他文件中。</p><h5 id="将整个文件内容复制到另一个文件中" tabindex="-1">将整个文件内容复制到另一个文件中 <a class="header-anchor" href="#将整个文件内容复制到另一个文件中" aria-label="Permalink to “将整个文件内容复制到另一个文件中”">​</a></h5><p>我们知道如何复制一行，那么整个文件的内容呢？也是可以的。比如说，您要将 <code>file1.txt</code> 的全部内容复制到 <code>file2.txt</code> 中。</p><p>先打开 <code>file2.txt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim file2.txt</span></span></code></pre></div><p>如果文件已经加载，您可以通过输入以下命令切换到 <code>file2.txt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffer 2</span></span></code></pre></div><p>将光标移动到您想要粘贴 <code>file1.txt</code> 的内容的位置。我想在 <code>file2.txt</code> 的第 5 行之后粘贴 <code>file1.txt</code> 的内容，所以我将光标移动到第 5 行。然后，键入以下命令并按回车键：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:r file1.txt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-12.png" alt=""></p><p>这里，<code>r</code> 代表 “read”。</p><p>现在您会看到 <code>file1.txt</code> 的内容被粘贴在 <code>file2.txt</code> 的第 5 行之后。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>line1</span></span>
<span class="line"><span>line2</span></span>
<span class="line"><span>line3</span></span>
<span class="line"><span>line4</span></span>
<span class="line"><span>line5</span></span>
<span class="line"><span>ostechnix</span></span>
<span class="line"><span>open source</span></span>
<span class="line"><span>technology</span></span>
<span class="line"><span>linux</span></span>
<span class="line"><span>unix</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-13.png" alt=""></p><p>要保存当前文件中的更改，请键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ZZ</span></span></code></pre></div><p>要保存所有文件的所有更改并退出 vim 编辑器，请输入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:wq</span></span></code></pre></div><h4 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to “方法二”">​</a></h4><p>另一种同时打开多个文件的方法是使用 <code>-o</code> 或 <code>-O</code> 标志。</p><p>要在水平窗口中打开多个文件，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim -o file1.txt file2.txt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/Edit-multiple-files-16.png" alt=""></p><p>要在窗口之间切换，请按 <code>CTRL-w w</code>（即按 <code>CTRL + w</code> 并再次按 <code>w</code>）。或者，您可以使用以下快捷方式在窗口之间移动：</p><ul><li><code>CTRL-w k</code> – 上面的窗口</li><li><code>CTRL-w j</code> – 下面的窗口</li></ul><p>要在垂直窗口中打开多个文件，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim -O file1.txt file2.txt file3.txt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/Edit-multiple-files-17.png" alt=""></p><p>要在窗口之间切换，请按 <code>CTRL-w w</code>（即按 <code>CTRL + w</code> 并再次按 <code>w</code>）。或者，使用以下快捷方式在窗口之间移动：</p><ul><li><code>CTRL-w l</code> – 左面的窗口</li><li><code>CTRL-w h</code> – 右面的窗口</li></ul><p>其他的一切都与方法一的描述相同。</p><p>例如，要列出当前加载的文件，请运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffers</span></span></code></pre></div><p>在文件之间切换：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffer 1</span></span></code></pre></div><p>打开其他文件，请键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:e file3.txt</span></span></code></pre></div><p>将文件的全部内容复制到另一个文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:r file1.txt</span></span></code></pre></div><p>方法二的唯一区别是，只要您使用 <code>ZZ</code> 保存对当前文件的更改，文件将自动关闭。然后，您需要依次键入 <code>:wq</code> 来关闭文件。但是，如果您按照方法一进行操作，输入 <code>:wq</code> 时，所有更改将保存在所有文件中，并且所有文件将立即关闭。</p><p>有关更多详细信息，请参阅手册页。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man vim</span></span></code></pre></div><h3 id="建议阅读" tabindex="-1">建议阅读 <a class="header-anchor" href="#建议阅读" aria-label="Permalink to “建议阅读”">​</a></h3><p>您现在掌握了如何在 Linux 中使用 vim 编辑器编辑多个文件。正如您所见，编辑多个文件并不难。Vim 编辑器还有更强大的功能。我们接下来会提供更多关于 Vim 编辑器的内容。</p><p>再见！</p><hr>`,113)),l("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.ostechnix.com/how-to-edit-multiple-files-using-vim-editor/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-edit-multiple-files-using-vim-editor/",-1)])]),_:1})]),l("p",null,[s[5]||(s[5]=i("作者：",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[6]||(s[6]=i(" 译者：",-1)),a(e,{href:"https://github.com/jessie-pang"},{default:t(()=>[...s[3]||(s[3]=[i("jessie-pang",-1)])]),_:1}),s[7]||(s[7]=i(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[10]||(s[10]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[i("Linux中国",-1)])]),_:1}),s[12]||(s[12]=i(" 荣誉推出",-1))])])}const C=n(c,[["render",g]]);export{y as __pageData,C as default};
